extern void __stdcall w28a_wps(unsigned short id, void *obj);  /* =_WPSetWaypoints@8 */

void __stdcall w28a_WNGSetWaypoints(short grp, void *obj)
{
    unsigned long x4;
    unsigned short *pw;
    int i = 0;
    if (w28a_wsizes[grp] > i) {
        x4 = grp * 4;
        pw = &w28a_wids[x4 * 2];
        do {
            w28a_wps(*pw, obj);
            pw++;
            i++;
        } while (w28a_wsizes[grp] > i);
    }
}

